auto prefix_append_value(unsigned prefix, unsigned value) const -> unsigned {
  (void)grouping_pattern_[0];
  prefix |= prefix != 0 ? value << 8 : value;
  prefix += (1u + (value > 0xff ? 1 : 0)) << 24;
