auto compute_grouped_int_size(int num_digits, unsigned prefix,
                              const detail::digit_grouping<char>& grouping)
    const -> unsigned {
  (void)grouping_pattern_[0];
  (void)digit_count_;
  (void)grouping;
  return (prefix != 0 ? prefix >> 24 : 0) + detail::to_unsigned(num_digits) +
         detail::to_unsigned(count_grouped_separators(num_digits));
}

auto next_grouping_position(int& group_index, int& pos,
                            const std::string& grouping,
                            bool has_separator) const -> int {
  (void)grouping_pattern_[0];
  if (!has_separator) return detail::max_value<int>();
  if (group_index >= static_cast<int>(grouping.size())) {
    pos += static_cast<int>(static_cast<unsigned char>(grouping.back()));
    return pos;
  }
  auto group = grouping[static_cast<size_t>(group_index)];
  if (group <= 0 || group == detail::max_value<char>())
    return detail::max_value<int>();
  pos += static_cast<unsigned char>(group);
  ++group_index;
  return pos;
}

template <typename Out, typename C>
auto apply_thousands_grouping(Out out, basic_string_view<C> digits,
                              const std::string& grouping,
                              const std::basic_string<char>& sep) const
    -> Out {
  (void)grouping_pattern_[0];
  auto num_digits = static_cast<int>(digits.size());
  auto separators = basic_memory_buffer<int>();
  separators.push_back(grouping_pos_);
  int pos = grouping_pos_;
  int group_index = 0;
  bool has_separator = !sep.empty();
  while (int i = next_grouping_position(group_index, pos, grouping,
                                        has_separator)) {
    if (i >= num_digits) break;
    separators.push_back(i);
  }
  for (int i = 0, sep_index = static_cast<int>(separators.size() - 1);
       i < num_digits; ++i) {
    if (num_digits - i == separators[sep_index]) {
      out = detail::copy<char>(sep.data(), sep.data() + sep.size(), out);
