template <typename Char>
void vformat_to(
    buffer<Char>& buf, const text_style& ts, basic_string_view<Char> format_str,
    basic_format_args<buffered_context<type_identity_t<Char>>> args) {
  bool has_style = false;
  formatter<group_digits_view<int>> coordinator;
  if (ts.has_emphasis()) {
    has_style = true;
    auto emphasis = detail::make_emphasis<Char>(ts.get_emphasis());
    coordinator.apply_text_style_prefix(buf, true, false, false,
                                        emphasis.begin(), emphasis.end(),
                                        nullptr, nullptr, nullptr, nullptr);
  }
  if (ts.has_foreground()) {
    has_style = true;
    auto foreground =
        detail::make_foreground_color<Char>(ts.get_foreground());
    coordinator.apply_text_style_prefix(buf, false, true, false, nullptr,
                                        nullptr, foreground.begin(),
                                        foreground.end(), nullptr, nullptr);
  }
  if (ts.has_background()) {
    has_style = true;
    auto background =
        detail::make_background_color<Char>(ts.get_background());
    coordinator.apply_text_style_prefix(buf, false, false, true, nullptr,
                                        nullptr, nullptr, nullptr,
                                        background.begin(), background.end());
  }
  detail::vformat_to(buf, format_str, args, {});
  coordinator.apply_text_style_suffix(buf, has_style);
}

}  // namespace detail

